// --- node body ---
// The feed declares ISO-8859-1. n8n's HTTP node hands us a decoded string; if
// Danish characters arrive mangled, set the node's response encoding rather than
// trying to repair them here — mojibake stored once is permanent.
//
// ⚠️ There are THREE jobindex_rss source rows, so this node receives THREE feed
// responses. It used to read `$input.first()` and parse only one of them — the
// first live run fetched all three feeds and silently discarded two, which is why
// a run that looked healthy produced no AI and no Data Science ads at all. The
// generic "alle jobs" feed happened to sort first and ate the entire run.
//
// Pair each response with its own source row rather than reusing source #1's id,
// or every ad is attributed to the wrong feed.
const sources = $('Fan Out Sources')
  .all()
  .map((i) => i.json)
  .filter((c) => c.source && c.source.kind === 'jobindex_rss');
const ctx0 = sources[0] ?? $('Fan Out Sources').first().json;
const MAX_NEW = 25; // politeness cap: each survivor costs two more fetches

const seen = new Set(ctx0.seen || []);
const perFeed = $input.all().map((item, i) => {
  // An `onError: continueRegularOutput` item carries `error` and no body. Parsing
  // '' yields [], so one dead feed costs its own items and nothing else.
  const xml = item.json.data ?? item.json.body ?? '';
  const src = sources[i] ?? sources[0];
  return parseJobindexFeed(xml)
    .filter((j) => j.url && !seen.has(SOURCE_KIND.jobindex + ' ' + j.external_id))
    .map((j) => ({ ...j, source_id: src && src.source ? src.source.id : null }));
});

// Round-robin across the feeds instead of concatenating them. The cap is global
// (25 survivors = 50 further fetches), and taking it in feed order would let the
// broadest feed spend the whole budget before the narrow, on-topic ones are
// reached — the same starvation that produced a run with zero AI ads.
const picked = [];
const taken = new Set();
for (let round = 0; picked.length < MAX_NEW; round++) {
  let anyLeft = false;
  for (const feed of perFeed) {
    if (round >= feed.length) continue;
    anyLeft = true;
    const job = feed[round];
    // The AI and Data Science feeds overlap heavily; without this the same ad is
    // fetched twice and stored twice.
    if (taken.has(job.external_id)) continue;
    taken.add(job.external_id);
    picked.push(job);
    if (picked.length >= MAX_NEW) break;
  }
  if (!anyLeft) break;
}

return picked.map((j) => ({ json: j }));

