// --- node body ---
// TheHub emits one schema.org JobPosting per job page. A page without one is
// skipped rather than guessed at: a row with a title and no description would
// score as a poor match for reasons that have nothing to do with the job.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const html = items[i].json.data ?? items[i].json.body ?? '';
  const meta = $('Parse Sitemap').all()[i]?.json ?? {};
  const ld = extractJobPostingLd(html);
  if (!ld) continue;
  const row = normalizeLdJobPosting(ld, { url: meta.url, sourceKind: 'thehub_sitemap' });
  out.push({
    json: {
      ...row,
      source_id: meta.source_id ?? null,
      dedupe_key: dedupeKey(row.company, row.title),
      apply_url: meta.url,
      categories: [],
    },
  });
}
return out;

