// --- node body ---
// `simple: false` on the Gmail node is what makes `html` exist at all: the
// simplified response carries headers and a snippet, and the snippet is a
// truncated preheader, not the job cards. The fallbacks mirror the HTTP nodes'
// `data ?? body` — n8n's shape here has changed between versions.
//
// No sender check. `parseLinkedInAlertEmail` already returns [] for anything that
// is not a LinkedIn digest, so a second filter would only add a way to
// accidentally drop everything.
const ctx = $('Fan Out Sources').first().json;
const MAX_ENRICH = 10; // politeness: each of these is one fetch of a public page

const seen = new Set(ctx.seen || []);
const fresh = new Set();
const jobs = [];

for (const item of $input.all()) {
  const m = item.json;
  const html = m.html ?? m.textAsHtml ?? m.body?.html ?? m.text ?? '';
  for (const job of parseLinkedInAlertEmail(html)) {
    // LinkedIn re-sends the same job for days, and the alert arrives twice daily,
    // so both a cross-run and a within-run guard are needed.
    // The seen-set is keyed on job_postings.source_kind, which is the SINGULAR
    // 'gmail_alert' — not the plural job_sources.kind that routed us here. Using
    // the plural here never matched, so the cross-run guard was dead and LinkedIn's
    // daily re-sends would have been re-fetched forever.
    if (seen.has(SOURCE_KIND.gmailAlert + ' ' + job.external_id) || fresh.has(job.external_id)) continue;
    fresh.add(job.external_id);
    jobs.push(job);
  }
}

// Everything found is ingested; only the first MAX_ENRICH are enriched. Capping
// the *jobs* instead would drop real postings for a cosmetic reason — the email
// already carries title, company and location, which is all the gate needs.
return jobs.map((job, i) => ({
  json: { ...job, source_id: ctx.source.id, enrich: i < MAX_ENRICH },
}));

