// --- node body ---
// LinkedIn is ingest-only: no API, and logged-in pages are never scraped. This
// fetches the same public page anyone would get, and is allowed to come back
// with nothing — probed 2026-08-25, it answers 200 with zero ld+json, so
// `og:description` is usually all there is. `neverError` on the HTTP node keeps a
// 999 or a timeout from failing the whole run.
const items = $input.all();
// The true branch of the IF node is exactly the enrich-flagged items, in order.
// Recomputing it from the parse node rather than reading a branch index keeps
// this independent of how n8n numbers IF outputs.
const metas = $('Parse Alert Emails').all().map((i) => i.json).filter((j) => j.enrich);
// If the two lists ever disagree in length, positional pairing would attach one
// job's ad body to a different job — a silently wrong description is worse than
// none, so the whole batch falls back to email-only.
const aligned = metas.length === items.length;

const out = [];
for (let i = 0; i < items.length; i++) {
  const meta = metas[i];
  if (!meta) continue;
  const html = items[i].json.data ?? items[i].json.body ?? '';
  const enrichment = aligned
    ? extractAlertPageEnrichment(html, { url: meta.url, sourceKind: SOURCE_KIND.gmailAlert })
    : null;
  out.push({
    json: buildAlertPosting(meta, {
      sourceKind: SOURCE_KIND.gmailAlert,
      sourceId: meta.source_id ?? null,
      enrichment,
    }),
  });
}
return out;

