// --- node body ---
// Past the politeness cap, so no page was fetched. The row is built from the
// email alone rather than dropped: it still carries title, company, location and
// the canonical URL, which is everything the gate reads.
return $input.all().map((item) => ({
  json: buildAlertPosting(item.json, {
    sourceKind: SOURCE_KIND.gmailAlert,
    sourceId: item.json.source_id ?? null,
    enrichment: null,
  }),
}));

