// --- node body ---
// Rule-only screening, before any model runs. Most of a Jobindex feed is
// droppable on a regex, and a 7B model on this Mac costs seconds per posting.
//
// A posting that fails the gate for EVERY profile is not posted at all — storing
// universally-rejected ads would fill the table with the 95% of the Danish job
// market that is not a software job. A posting that passes for at least one
// profile is posted with a verdict per profile, so a drop stays auditable.
const ctx = $('Fan Out Sources').first().json;
const profiles = ctx.profiles || [];
const now = new Date();
const out = [];

for (const item of $input.all()) {
  const p = item.json;
  const matches = profiles.map((profile) => {
    const g = cheapGate(p, profile, now);
    return {
      profile_id: profile.id,
      gate_verdict: g.verdict,
      gate_reason: g.reason,
      score: null,
    };
  });
  if (!matches.some((m) => m.gate_verdict === 'pass')) continue;
  const { categories, ...row } = p;
  out.push({ json: { ...row, matches } });
}
return out;

// Batch every surviving posting into one request. job-ingest caps a batch at 200.
const postings = $input.all().map((i) => i.json);
if (postings.length === 0) return [];
return [{ json: { user_id: $env.NEXUS_USER_ID, postings } }];
